import csv
import io

# Read and check RFC 4180 compliance
with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)
    num_cols = len(header)
    print(f'Header columns: {num_cols}')

    row_num = 0
    for row in reader:
        row_num += 1
        if len(row) != num_cols:
            print(f'Row {row_num}: Expected {num_cols} columns, got {len(row)}')
        # Check for any issues
        for i, cell in enumerate(row):
            if ',' in cell and '\"' not in cell:
                print(f'Row {row_num}, col {i}: Has comma without quotes: {repr(cell)}')
            if '\"' in cell:
                if cell.count('\"') % 2 != 0:
                    print(f'Row {row_num}, col {i}: Unbalanced quotes: {repr(cell)}')
    print(f'Total rows checked: {row_num}')
